data:
{
    // Settings
    "settings": *[_type == "settings"][0] {
        "shortBio": coalesce(shortBio[$lang], shortBio.en),

    seo {
        "title": coalesce(title[$lang], title.en),
        "description": coalesce(description[$lang], description.en),
        image,
        noIndex,
    }
,
    },
    // About
    "about": *[_type == "about"][0] {
        "bio": coalesce(bio[$lang], bio.en),
        infoBlocks[] {
            _key,
            "title": coalesce(title[$lang], title.en),
            "text": coalesce(text[$lang], text.en),
        },
        contact {
            instagram {
                label,
                handle,
                url,
            },
            email {
                label,
                address,
            },
        },
        representation {
            "label": coalesce(label[$lang], label.en),
            list[] {
                _key,
                content,
            }
        },
    },
}

    *[_type == "series"][0] {
        list[]-> {
            "name": coalesce(name[$lang], name.en),
            "slug": slug.current,
            year,
            thumbnail,

    gradient {
        "start": string(start.rgb.r) + " " + string(start.rgb.g) + " " + string(start.rgb.b),
        "end": string(end.rgb.r) + " " + string(end.rgb.g) + " " + string(end.rgb.b),
    }
,
        },

    seo {
        "title": coalesce(title[$lang], title.en),
        "description": coalesce(description[$lang], description.en),
        image,
        noIndex,
    }
,
    }
